def parse_row(line: str) -> list[str]:
    fields = []
    current_field = ""
    in_quotes = False

    for char in line:
        if char == '"':
            # Toggle quote state, but only on the first double-quote inside a field.
            if not in_quotes and (char != ','):
                in_quotes = True
            elif in_quotes and char == '"' and current_field.count('"') % 2 == 1:
                # Closing quote for an odd number of quotes seen so far.
                in_quotes = False
        else:
            if not in_quotes:
                current_field += char
            else:
                current_field += char

        if char == ',' and not in_quotes:
            fields.append(current_field)
            current_field = ""

    # Append the last field.
    fields.append(current_field)
    return fields
